INSERT INTO monster VALUES (636,'Monstrous Scorpion','Monstrous Scorpion, Large',NULL,'Large','Vermin',NULL,'5d8+10 (32 hp)','+0','50 ft. (10 squares)','16 (-1 size, +7 natural), touch 9, flat-footed 16','+3','+11','Claw +6 melee (1d6+4)','2 claws +6 melee (1d6+4) and sting +1 melee (1d6+2 plus poison)','10 ft.','5 ft.','Constrict 1d6+4, improved grab, poison','Darkvision 60 ft., tremorsense 60 ft., vermin traits','Fort +6, Ref +1, Will +1','Str 19, Dex 10, Con 14, Int -, Wis 10, Cha 2','Climb +8, Hide +0, Spot +4',NULL,'-',NULL,'Warm deserts','Solitary or colony (2-5)','3','1/10 coins; 50% goods; 50% items',NULL,'6-9 HD (Large)','-','Constrict (Ex), Improved Grab (Ex), Poison (Ex)','Large monstrous scorpion; CR 3; Large vermin; HD 5d8+10; hp 32; Init +0; Spd 50 ft. (10 squares); AC 16 (-1 size, +7 natural), touch 9, flat-footed 16; Base Atk +3; Grp +11; Atk +6 melee (1d6+4, claw); Full Atk +6 melee (1d6+4, 2 claws) and +1 melee (1d6+2 plus poison, sting); Space/Reach 10 ft./5 ft.; SA Constrict 1d6+4, improved grab, poison; SQ Darkvision 60 ft., tremorsense 60 ft., vermin traits; AL N; SV Fort +6, Ref +1, Will +1; Str 19, Dex 10, Con 14, Int -, Wis 10, Cha 2\n\nSkills and Feats: Climb +8, Hide +0, Spot +4; -','\n      <div topic=\"Monstrous Scorpion\" level=\"2\"><p><h2>Monstrous Scorpion</h2></p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Monstrous Scorpion, Large</b><br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Vermin<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>5d8+10 (32 hp)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>50 ft. (10 squares)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>16 (-1 size, +7 natural), touch 9, flat-footed 16<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+3/+11<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Claw +6 melee (1d6+4)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>2 claws +6 melee (1d6+4) and sting +1 melee (1d6+2 plus poison)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./5 ft.<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Constrict 1d6+4, improved grab, poison<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., tremorsense 60 ft., vermin traits<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +6, Ref +1, Will +1<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 19, Dex 10, Con 14, Int -, Wis 10, Cha 2<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +8, Hide +0, Spot +4<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>-<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm deserts<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or colony (2-5)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>3<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>1/10 coins; 50% goods; 50% items<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>6-9 HD (Large)<br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n\n</tr>\n</table><p/><p>Monstrous scorpions are likely to attack any creature that approaches, and they usually charge when attacking prey.</p><div topic=\"Constrict\" level=\"8\"><p><b>Constrict (Ex):</b> A monstrous scorpion deals automatic claw damage on a successful grapple check.</p>\n</div><div topic=\"Improved Grab\" level=\"8\"><p><b>Improved Grab (Ex):</b> To use this ability, a monstrous scorpion must hit with a claw attack. A monstrous scorpion can use either its Strength modifier or Dexterity modifier for grapple checks, whichever is better.</p>\n</div><div topic=\"Poison\" level=\"8\"><p><b>Poison (Ex):</b> A monstrous scorpion has a poisonous sting. The details vary by the scorpion\'s size, as follows. The save DCs are Constitution- based. The indicated damage is initial and secondary damage.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td><b>Size</b><br/></td>\n<td><b>Fort DC</b><br/></td>\n<td><b>Damage</b><br/></td>\n<td><b>Size</b><br/></td>\n<td><b>Fort DC</b><br/></td>\n<td><b>Damage</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Tiny<br/></td>\n<td>12<br/></td>\n<td>1 Con<br/></td>\n<td>Huge<br/></td>\n<td>18<br/></td>\n<td>1d6 Con<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Small<br/></td>\n<td>12<br/></td>\n<td>1d2 Con<br/></td>\n<td>Gargantuan<br/></td>\n<td>23<br/></td>\n<td>1d8 Con<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Medium<br/></td>\n<td>13<br/></td>\n<td>1d3 Con<br/></td>\n<td>Colossal<br/></td>\n<td>33<br/></td>\n<td>1d10 Con<br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Large<br/></td>\n<td>14<br/></td>\n<td>1d4 Con<br/></td>\n<td/>\n<td/>\n<td/>\n\n</tr>\n</table>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A monstrous scorpion has a +4 racial bonus on Climb, Hide, and Spot checks.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersVermin');
